    pub(crate) fn put_journal_producer(
        &self,
        manifest: &crate::JournalProducerManifest,
        origin: &str,
        idempotency_key: &str,
    ) -> anyhow::Result<crate::JournalAppendCommit> {
        let prepared = crate::journal_kernel::JournalKernel::prepare_producer(manifest)?;
        let commit = self.workspace_registry.lock().unwrap().put_journal_producer(
            manifest,
            origin,
            idempotency_key,
        )?;
        if !commit.replayed {
            // Installation is version-monotonic, so concurrent successful
            // updates cannot publish their compiled validators out of order.
            self.journal_kernel.install_prepared_producer(prepared);
            self.publish_journal_event();
        }
        Ok(commit)
    }

    pub(crate) fn append_journal_ingress(
        &self,
        ingress: &crate::JournalIngress,
        origin: &str,
        idempotency_key: &str,
    ) -> anyhow::Result<crate::JournalAppendCommit> {
        let validated = self.journal_kernel.validate_ingress(ingress)?;
        let commit = if self.journal_ingress.enabled() {
            self.journal_ingress.send_producer(
                ingress.clone(),
                validated,
                origin.into(),
                idempotency_key.into(),
            )?
        } else {
            let commit = self.workspace_registry.lock().unwrap().append_journal_ingress(
                ingress,
                &validated,
                origin,
                idempotency_key,
            )?;
            if !commit.replayed {
                self.publish_journal_event();
            }
            commit
        };
        if !commit.replayed && ingress.producer_id == crate::agent_hooks::AGENT_HOOK_PRODUCER_ID {
            self.fold_agent_roster(&commit);
        }
        Ok(commit)
    }

    /// Fold one fresh `agent.*` journal commit into the roster reducer and
    /// apply the resulting deltas (projection commits, change broadcasts).
    /// The roster is derived state: this fold plus the startup tail replay
    /// are its only writers, so the journal fully determines it. Best
    /// effort by design: a hook may outlive its terminal, and a journal
    /// append must never start failing because a view cannot update.
    fn fold_agent_roster(&self, commit: &crate::JournalAppendCommit) {
        use crate::journal_reducers::{
            AGENT_ROSTER_REDUCER_ID, AGENT_ROSTER_REDUCER_VERSION, RosterEvent,
            SOCKET_REPORT_ADAPTER,
        };
        // Journal commits can complete out of order on different ingress
        // threads. This fence makes the fold and terminal retirement one
        // lifecycle, so a later commit cannot advance the cursor past an
        // earlier event or write an older snapshot after retirement.
        let _lifecycle = self.agent_roster_lifecycle.lock().unwrap();
        let (saved_cursor, snapshot_dirty) = {
            let host = self.agent_roster.lock().unwrap();
            (host.cursor, host.snapshot_dirty)
        };
        if commit.sequence <= saved_cursor && !snapshot_dirty {
            return;
        }

        // Read the durable records, not the caller's ingress. The stored row
        // has the committed timestamp and is exactly what startup replay uses.
        // Replay every record through this commit so out-of-order callers
        // cannot lose an earlier event to the global cursor.
        let mut records = Vec::new();
        let mut scan_cursor = saved_cursor;
        let mut reached_commit = commit.sequence <= saved_cursor;
        while !reached_commit {
            let page = match self
                .workspace_registry
                .lock()
                .unwrap()
                .session_journal_after(scan_cursor, 512)
            {
                Ok(page) => page,
                Err(error) => {
                    let _ = error;
                    eprintln!("cmux-tui: reading committed agent events failed");
                    return;
                }
            };
            if page.records.is_empty() {
                break;
            }
            let mut progressed = false;
            for record in page.records {
                if record.sequence <= scan_cursor {
                    continue;
                }
                if record.sequence > commit.sequence {
                    break;
                }
                scan_cursor = record.sequence;
                records.push(record);
                progressed = true;
                if scan_cursor == commit.sequence {
                    reached_commit = true;
                    break;
                }
            }
            if !progressed {
                break;
            }
        }
        if !reached_commit {
            // The writer acknowledged a commit that the reader cannot see
            // yet. Keep the in-memory and durable cursor unchanged; a later
            // agent commit retries the entire missing prefix.
            return;
        }

        let (deltas, cursor, snapshot) = {
            let mut host = self.agent_roster.lock().unwrap();
            let mut deltas = Vec::new();
            for record in &records {
                let record_deltas = host.roster.apply(&RosterEvent::from_record(record));
                let echo = record
                    .payload
                    .get("adapter")
                    .and_then(|adapter| adapter.get("id"))
                    .and_then(Value::as_str)
                    == Some(SOCKET_REPORT_ADAPTER);
                if !echo {
                    deltas.extend(
                        record_deltas.into_iter().map(|delta| (delta, record.kind.clone())),
                    );
                }
                host.cursor = record.sequence;
            }
            // Mark dirty before any database work. If projection or snapshot
            // persistence fails, a later fold retries the durable snapshot.
            host.snapshot_dirty = true;
            (deltas, host.cursor, host.roster.snapshot().to_string())
        };

        // Keep side effects in journal order under the same lifecycle fence.
        // A later fold therefore cannot publish a newer projection before an
        // earlier fold's AgentChanged event.
        for (delta, kind) in deltas {
            self.apply_roster_delta(delta, &kind);
        }
        let persisted = self.workspace_registry.lock().unwrap().put_journal_reducer_state(
            AGENT_ROSTER_REDUCER_ID,
            AGENT_ROSTER_REDUCER_VERSION,
            cursor,
            &snapshot,
        );
        let mut host = self.agent_roster.lock().unwrap();
        if let Err(error) = persisted {
            let _ = error;
            eprintln!("cmux-tui: persisting the agent roster snapshot failed");
            host.snapshot_dirty = true;
        } else {
            host.snapshot_dirty = false;
        }
    }

    /// Apply one roster delta's side effects: the durable agent projection
    /// commit and the agent-changed broadcast remote frontends converge on.
    /// A removal commits the done state (history keeps the exit; the roster
    /// already dropped the live entry).
    fn apply_roster_delta(&self, delta: crate::journal_reducers::RosterDelta, kind: &str) {
        use crate::journal_reducers::RosterDelta;
        let (terminal_id, state, source, session, agent_adapter) = match delta {
            RosterDelta::Upsert { terminal_id, entry } => {
                let Some(source) = entry.agent_source() else { return };
                (terminal_id, entry.agent_state(), source, entry.session.clone(), entry.agent)
            }
            RosterDelta::Remove { terminal_id } => {
                (terminal_id, AgentState::Done, AgentSource::Hook, None, None)
            }
        };
        let Ok(terminal_id) = TerminalPublicId::parse(&terminal_id) else { return };
        let Some(surface) = self.resource_surface_for_terminal(&terminal_id) else { return };
        let mutation = match WorkspaceMutation::new(
            format!("roster-{}", crate::workspace_registry::new_uuid_v4()),
            "journal-reducer",
        ) {
            Ok(mutation) => mutation,
            Err(_) => return,
        };
        let fingerprint = serde_json::json!({
            "operation":"agent.report",
            "surface":surface,
            "state":state.as_str(),
            "source":source.as_str(),
            "source_session":session,
        });
        if let Err(error) = self.commit_agent_report(
            AgentReportTarget::Surface(surface),
            state,
            source,
            session,
            None,
            &mutation,
            &fingerprint,
            AgentReportOrigin::RosterFold,
            agent_adapter,
        ) {
            eprintln!(
                "cmux-tui: agent projection update for {terminal_id} ({kind}) failed: {error}"
            );
        }
    }

    /// Record a direct socket/SDK agent report in the journal so the roster
    /// reducer (and any future reducer) sees every agent intent in one log.
    /// The event wears the agent-hook payload shape with a dedicated
    /// adapter, and the fold recognizes that adapter as an echo whose
    /// projection commit already happened.
    fn append_agent_report_echo(
        &self,
        terminal_id: &TerminalPublicId,
        state: AgentState,
        source: AgentSource,
        session: Option<&str>,
        updated_at_ms: u64,
    ) {
        use crate::journal_reducers::{SOCKET_REPORT_ADAPTER, SOCKET_REPORT_NATIVE_EVENT};
        let ingress = crate::JournalIngress {
            producer_id: crate::agent_hooks::AGENT_HOOK_PRODUCER_ID.into(),
            manifest_version: crate::agent_hooks::AGENT_HOOK_MANIFEST_VERSION,
            kind: "agent.state.changed".into(),
            schema_version: 1,
            occurred_at_ms: None,
            subjects: vec![crate::JournalSubject {
                kind: "terminal".into(),
                id: terminal_id.to_string(),
            }],
            sensitivity: Some(crate::JournalSensitivity::Sensitive),
            payload: serde_json::json!({
                "format": crate::agent_hooks::AGENT_HOOK_FORMAT,
                "adapter": {"id": SOCKET_REPORT_ADAPTER, "version": 1},
                "native_event": SOCKET_REPORT_NATIVE_EVENT,
                "normalized": {
                    "state": state.as_str(),
                    "source": source.as_str(),
                    "source_session": session,
                    // The direct commit's timestamp, so the roster mirrors
                    // the projection exactly instead of stamping fold time.
                    "updated_at_ms": updated_at_ms.to_string(),
                },
                "native": {},
            }),
            causation_id: None,
            correlation_id: None,
        };
        let idempotency_key =
            format!("agent-report-echo-{}", crate::workspace_registry::new_uuid_v4());
        if let Err(error) = self.append_journal_ingress(&ingress, "agent-report", &idempotency_key)
        {
            eprintln!("cmux-tui: journaling an agent report for {terminal_id} failed: {error}");
        }
    }

