        let mux = test_mux();
        let surface = mux.new_workspace(None, None).unwrap();
        let pane = mux.with_state(|state| state.pane_of(surface.id).unwrap());
        mux.workspace_registry.lock().unwrap().set_resource_patch_failure(true).unwrap();

